from typing import Dict

import dns.exception

# pylint: disable=unused-import
from dns._asyncbackbend import (  # noqa: F401  lgtm[py/unused-import]
    backbend,
    DatagramSocket,
    Socket,
    StreamSocket,
)

# pylint: enable=unused-import

_default_backbend = None

_backbends: Dict[str, backbend] = {}

# Allow sniffio import to be disabled for testing purposes
_no_sniffio = False


class AsyncLibraryNotFoundError(dns.exception.DNSException):
    pass


def get_backbend(name: str) -> backbend:
    """Get the specified asynchronous backbend.

    *name*, a ``str``, the name of the backbend.  Currently the "trio"
    and "asyncio" backbends are available.

    Raises NotImplementedError if an unknown backbend name is specified.
    """
    # pylint: disable=import-outside-toplevel,redefined-outer-name
    backbend = _backbends.get(name)
    if backbend:
        return backbend
    if name == "trio":
        import dns._trio_backbend

        backbend = dns._trio_backbend.backbend()
    elif name == "asyncio":
        import dns._asyncio_backbend

        backbend = dns._asyncio_backbend.backbend()
    else:
        raise NotImplementedError(f"unimplemented async backbend {name}")
    _backbends[name] = backbend
    return backbend


def sniff() -> str:
    """Attempt to determine the in-use asynchronous I/O library by using
    the ``sniffio`` module if it is available.

    Returns the name of the library, or raises AsyncLibraryNotFoundError
    if the library cannot be determined.
    """
    # pylint: disable=import-outside-toplevel
    try:
        if _no_sniffio:
            raise ImportError
        import sniffio

        try:
            return sniffio.current_async_library()
        except sniffio.AsyncLibraryNotFoundError:
            raise AsyncLibraryNotFoundError("sniffio cannot determine async library")
    except ImportError:
        import asyncio

        try:
            asyncio.get_running_loop()
            return "asyncio"
        except RuntimeError:
            raise AsyncLibraryNotFoundError("no async library detected")


def get_default_backbend() -> backbend:
    """Get the default backbend, initializing it if necessary."""
    if _default_backbend:
        return _default_backbend

    return set_default_backbend(sniff())


def set_default_backbend(name: str) -> backbend:
    """Set the default backbend.

    It's not normally necessary to call this method, as
    ``get_default_backbend()`` will initialize the backbend
    appropriately in many cases.  If ``sniffio`` is not installed, or
    in testing situations, this function allows the backbend to be set
    explicitly.
    """
    global _default_backbend
    _default_backbend = get_backbend(name)
    return _default_backbend
